def _smoothstep(g, value):
    t = g.math('MINIMUM', 1., g.math('MAXIMUM', 0., value))
    return g.math('MULTIPLY', g.math('MULTIPLY', t, t),
                  g.math('SUBTRACT', 3., g.math('MULTIPLY', 2., t)))


def _lerp(g, a, b, t):
    return g.vector('ADD', a, g.vector('SCALE', g.vector('SUBTRACT', b, a), t))


def _positive_quads(g, mesh, index, position):
    corners = []
    for k in range(4):
        corner = g.node('GeometryNodeCornersOfFace', 'Bundle quad corner '+str(k))
        g.set(index, corner.inputs['Face Index'])
        corner.inputs['Sort Index'].default_value = k
        vertex = g.node('GeometryNodeVertexOfCorner', 'Bundle quad corner vertex')
        g.set(corner.outputs['Corner Index'], vertex.inputs['Corner Index'])
        corners.append(g.sample(mesh, position, vertex.outputs['Vertex Index'], 'FLOAT_VECTOR'))
    checks = []
    for k in range(4):
        a, b, c = (corners[(k+j) % 4] for j in range(3))
        cross = g.vector('CROSS_PRODUCT', g.vector('SUBTRACT', b, a),
                         g.vector('SUBTRACT', c, b))
        checks.append(g.compare(g.component(cross, 'Z'), 1e-10, 'GREATER_THAN'))
    return g.stat(mesh, g.all(*checks), 'FACE')


